+      Kokkos::parallel_reduce(Kokkos::RangePolicy<ExecSpace>(0, 0), f,
+                              reducer_scalar);
+      ASSERT_FALSE(lor_scalar);
+    }
+
     {
       Kokkos::View<Scalar, Kokkos::HostSpace> lor_view("View");
       lor_view() = init;
